{
  "implementation": "def solve(case):
    passing = case['passing']
    failing = case['failing']
    required_diff = case['required_difference']
    unresolved_diff = case.get('unresolved_difference', [])
    if not isinstance(passing, list) or not isinstance(failing, list) or not isinstance(required_diff, list) or not isinstance(unresolved_diff, list):
        raise ValueError('Invalid input types')
    pass_set = set(passing)
    diff = []
    for item in failing:
        if item not in pass_set:
            diff.append(item)
    req_set = set(required_diff)
    unres_set = set(unresolved_diff)
    if not req_set.issubset(diff):
        raise ValueError('required_difference not subset of diff')
    if req_set & unres_set:
        raise ValueError('required_difference and unresolved_difference intersect')
    test_count = [0]
    def test(subset):
        test_count[0] += 1
        sset = set(subset)
        if not unres_set.isdisjoint(sset):
            return 'UNRESOLVED'
        if req_set.issubset(sset):
            return 'FAIL'
        return 'PASS'
    cs = diff[:]
    n = 2
    while len(cs) >= 2:
        subset_size = max(1, len(cs) // n)
        reduced = False
        for i in range(n):
            start = i * subset_size
            end = min(start + subset_size, len(cs))
            subset = cs[start:end]
            complement = cs[:start] + cs[end:]
            res = test(complement)
            if res == 'FAIL':
                cs = complement
                n = max(n - 1, 2)
                reduced = True
                break
            res = test(subset)
            if res == 'FAIL':
                cs = subset
                n = max(n - 1, 2)
                reduced = True
                break
        if not reduced:
            if n < len(cs):
                n = min(2 * n, len(cs))
            else:
                break
    return {'isolated_difference': cs, 'tests': test_count[0]}"
}
